static NSString *decodeCheat(void) {
    NSData *d = [[NSData alloc] initWithBase64EncodedString:@(g_cheatB64) options:0];
    if (!d) return nil;
    return [[NSString alloc] initWithData:d encoding:NSUTF8StringEncoding];
}
static UIImage *decodeBallImage(void) {
    NSData *d = [[NSData alloc] initWithBase64EncodedString:@(g_ballPngB64) options:0];
    if (!d) return nil;
    return [UIImage imageWithData:d];
}

static void syncFlagToJS(NSString *key, BOOL val) {
    if (!g_injected) return;
    seEval([NSString stringWithFormat:@"__XXC.setFlag('%@', %@);", key, val ? @"true" : @"false"]);
}
static void syncSpdToJS(NSString *key, int lvl) {
    if (!g_injected) return;
    seEval([NSString stringWithFormat:@"__XXC.setSpd('%@', %d);", key, lvl]);
}

// 前向声明
@class FloatGlassButton;
@interface FloatGlassPanel : UIView
- (void)fg_close;
- (void)refreshButtons;
@end
static FloatGlassPanel *g_panel = nil;
static FloatGlassButton *g_floatBtn = nil;
static UIWindow *fg_keyWindow(void);
static void fg_toast(NSString *msg);
void updateStatusLabel(void);

void updateStatusLabel(void) {
    if (!g_statusLabel) return;
    NSString *inj = g_injected ? @"JS 注入 ✓ 功能即时生效"
                   : (g_engineOk ? @"引擎就绪 正在注入…" : @"等待游戏引擎…");
    g_statusLabel.text = inj;
}

static void injectTick(void) {
    if (g_injected) return;
    if (!g_execBase || !g_eval) return;
    void *se = seInstance();
    if (!se) {
        static int n1 = 0;
        if (++n1 % 15 == 1) xlog(@"waiting: se singleton still NULL");
        return;
    }
    if (!g_engineOk) {
        bool ok = g_eval(se, "1", 1, NULL, "XXC_PROBE");
        if (!ok) {
            static int n2 = 0;
            if (++n2 % 15 == 1) xlog(@"probe fail se=%p (isolate not on main thread?)", se);
            return;
        }
        g_engineOk = YES;
        xlog(@"se engine ok se=%p", se);
        dispatch_async(dispatch_get_main_queue(), ^{ updateStatusLabel(); });
    }
    NSString *js = decodeCheat();
    if (!js) { xlog(@"ERROR b64 decode"); g_injected = YES; return; }
    // ⚠️ len 必须用 UTF8 字节数：js.length 是 UTF-16 单元数，含中文注释时脚本被截断 → 语法异常 → ok=0
    const char *cstr = js.UTF8String;
    unsigned clen = (unsigned)strlen(cstr);
    bool ok = g_eval(se, cstr, clen, NULL, "xxcheat.js");
    // 验证：cheat.js 加载成功后写标记文件 Documents/xxcheat_injected.flag
    NSString *flagPath = [NSHomeDirectory() stringByAppendingPathComponent:@"Documents/xxcheat_injected.flag"];
    BOOL verified = [[NSFileManager defaultManager] fileExistsAtPath:flagPath];
    if (ok && verified) {
        g_injected = YES;
        xlog(@"inject OK cheat_len=%u", clen);
        [[NSFileManager defaultManager] removeItemAtPath:flagPath error:nil];
        syncFlagToJS(@"kill", g_kill);
        syncFlagToJS(@"inv",  g_inv);
        syncFlagToJS(@"ad",   g_ad);
        syncSpdToJS(@"cd",  g_cd);
        syncSpdToJS(@"eng", g_eng);
        dispatch_async(dispatch_get_main_queue(), ^{ updateStatusLabel(); });
    } else {
        static int n3 = 0;
        if (++n3 % 5 == 1) xlog(@"inject retry ok=%d verified=%d", ok, verified);
    }
}

// ===== 卡密验证 =====
static NSString *g_cardKeys[10] = {
    @"NnKUJxbpptMQB", @"Cbf46DPzvqZvv", @"RHqPYB23uACGA", @"3pi02sniSlA00",
    @"dILhErfYZjEPX", @"1r4dB627SX9EJ", @"MGhJrbcF478bp", @"5PPNI3PDVKftJ",
    @"q1QRJlsZNd9q3", @"pAkg4Fcq8vjwo"
};
static BOOL g_activated = NO;
static UITextField *g_cardField = nil;

static BOOL validateCard(NSString *in) {
    if (!in.length) return NO;
    NSString *s = [in stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
    for (int i = 0; i < 10; i++) {
        if ([s isEqualToString:g_cardKeys[i]]) return YES;
    }
    return NO;
}

static void loadActivation(void) {
    // 本地记录：验证通过一次永久有效（keychain 级持久化用 NSUserDefaults 足够）
    g_activated = [NSUserDefaults.standardUserDefaults boolForKey:@"xxc_activated"];
}

static void onActivated(void) {
    g_activated = YES;
    [NSUserDefaults.standardUserDefaults setBool:YES forKey:@"xxc_activated"];
    if (g_panel) {
        // 移除卡密视图，恢复功能按钮
        for (UIView *sub in g_panel.subviews) {
            if (sub.tag >= 900) { [sub removeFromSuperview]; }
        }
        for (int i = 0; i < 5; i++) {
            UIButton *b = g_btns[i];
            b.hidden = NO;
        }
        g_statusLabel.hidden = NO;
        [g_panel refreshButtons];
        updateStatusLabel();
    }
    fg_toast(@"激活成功");
    xlog(@"card activated");
}

static void showCardUI(void); // 前向声明

static void showCardUI(void) {
    if (!g_panel) return;
    CGFloat W = g_panel.bounds.size.width;
    // 半透明遮罩层（挡住功能按钮）
    UIView *mask = [[UIView alloc] initWithFrame:g_panel.bounds];
    mask.tag = 900;
    mask.backgroundColor = [UIColor colorWithWhite:0.0 alpha:0.55];
    mask.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;
    [g_panel addSubview:mask];

    UILabel *tl = [[UILabel alloc] initWithFrame:CGRectMake(0, 60, W, 24)];
    tl.tag = 901;
    tl.text = @"请输入卡密";
    tl.textColor = [UIColor colorWithRed:0.55 green:0.8 blue:1.0 alpha:1.0];
    tl.font = [UIFont boldSystemFontOfSize:17];
    tl.textAlignment = NSTextAlignmentCenter;
    tl.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleBottomMargin;
    [mask addSubview:tl];

    g_cardField = [[UITextField alloc] initWithFrame:CGRectMake(30, 100, W - 60, 42)];
    g_cardField.tag = 902;
    g_cardField.placeholder = @"粘贴卡密";
    g_cardField.textAlignment = NSTextAlignmentCenter;
    g_cardField.textColor = UIColor.whiteColor;
    g_cardField.font = [UIFont systemFontOfSize:15];
    g_cardField.backgroundColor = [UIColor colorWithWhite:1.0 alpha:0.12];
    g_cardField.layer.cornerRadius = 10;
    g_cardField.autocorrectionType = UITextAutocorrectionTypeNo;
    g_cardField.autocapitalizationType = UITextAutocapitalizationTypeNone;
    g_cardField.keyboardType = UIKeyboardTypeASCIICapable;
    g_cardField.clearButtonMode = UITextFieldViewModeWhileEditing;
    g_cardField.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleBottomMargin;
    [mask addSubview:g_cardField];

    UIButton *ok = [UIButton buttonWithType:UIButtonTypeSystem];
    ok.tag = 903;
    ok.frame = CGRectMake(30, 156, W - 60, 42);
    ok.layer.cornerRadius = 10;
    ok.backgroundColor = [UIColor colorWithRed:0.10 green:0.42 blue:0.22 alpha:0.95];
    [ok setTitle:@"激 活" forState:UIControlStateNormal];
    ok.titleLabel.font = [UIFont boldSystemFontOfSize:16];
    ok.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleBottomMargin;
    [ok addTarget:g_panel action:@selector(fg_cardOk:) forControlEvents:UIControlEventTouchUpInside];
    [mask addSubview:ok];

    UILabel *tip = [[UILabel alloc] initWithFrame:CGRectMake(30, 206, W - 60, 30)];
    tip.tag = 904;
    tip.text = @"卡密一次激活 永久有效";
    tip.textColor = [UIColor colorWithWhite:1.0 alpha:0.45];
    tip.font = [UIFont systemFontOfSize:11];
    tip.textAlignment = NSTextAlignmentCenter;
    tip.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleBottomMargin;
    [mask addSubview:tip];

    // 隐藏功能按钮与状态行
    for (int i = 0; i < 5; i++) g_btns[i].hidden = YES;
    g_statusLabel.hidden = YES;
}

@interface FloatGlassButton : UIControl
@property (nonatomic, strong) UIView *glassView;
@end
@implementation FloatGlassButton
- (instancetype)initWithSize:(CGFloat)size {
    if (self = [super initWithFrame:CGRectMake(0, 0, size, size)]) {
        self.backgroundColor = [UIColor clearColor];

        // 图片贴图（用户提供的鸡鸡人形象，圆形裁剪）
        UIImageView *iv = [[UIImageView alloc] initWithFrame:self.bounds];
        iv.image = decodeBallImage();
        iv.contentMode = UIViewContentModeScaleAspectFill;
        iv.clipsToBounds = YES;
        iv.layer.cornerRadius = size / 2.0;
        iv.userInteractionEnabled = NO;
        [self addSubview:iv];

        // 玻璃高光（保留液态质感，压在图片上）
        CAGradientLayer *sheen = [CAGradientLayer layer];
        sheen.frame = self.bounds;
        sheen.colors = @[(__bridge id)[UIColor colorWithWhite:1.0 alpha:0.35].CGColor,
                         (__bridge id)[UIColor colorWithWhite:1.0 alpha:0.0].CGColor];
        sheen.startPoint = CGPointMake(0.5, 0.0);
        sheen.endPoint   = CGPointMake(0.5, 0.55);
        [_glassView addSubview:sheen];

        CABasicAnimation *breathe = [CABasicAnimation animationWithKeyPath:@"opacity"];
        breathe.fromValue = @0.6; breathe.toValue = @0.95;
        breathe.duration = 2.6; breathe.autoreverses = YES; breathe.repeatCount = HUGE_VALF;
        [sheen addAnimation:breathe forKey:@"fg_breathe"];

        CGFloat px = 1.0 / [UIScreen mainScreen].scale;
        self.layer.borderWidth = px;
        self.layer.borderColor = [UIColor colorWithWhite:1.0 alpha:0.55].CGColor;
        self.layer.cornerRadius = size / 2.0;


        UIPanGestureRecognizer *pan = [[UIPanGestureRecognizer alloc] initWithTarget:self action:@selector(fg_pan:)];
        [self addGestureRecognizer:pan];
        UITapGestureRecognizer *tap = [[UITapGestureRecognizer alloc] initWithTarget:self action:@selector(fg_tap:)];
        [tap requireGestureRecognizerToFail:pan];
        [self addGestureRecognizer:tap];
    }
    return self;
}
- (void)fg_pan:(UIPanGestureRecognizer *)g {
    UIView *sv = self.superview; if (!sv) return;
    if (g.state == UIGestureRecognizerStateChanged) {
        CGPoint t = [g translationInView:sv]; CGPoint c = self.center;
        c.x += t.x; c.y += t.y;
        CGFloat hw = self.frame.size.width/2.0, hh = self.frame.size.height/2.0;
        c.x = MAX(hw, MIN(c.x, sv.bounds.size.width - hw));
        c.y = MAX(hh, MIN(c.y, sv.bounds.size.height - hh));
        self.center = c; [g setTranslation:CGPointZero inView:sv];
    } else if (g.state == UIGestureRecognizerStateEnded) {
        CGFloat W = sv.bounds.size.width; CGPoint c = self.center;
        CGFloat margin = self.frame.size.width/2.0 + 8.0;
        c.x = (c.x < W/2.0) ? margin : (W - margin);
        [UIView animateWithDuration:0.25 delay:0 options:UIViewAnimationOptionCurveEaseOut
            animations:^{ self.center = c; } completion:nil];
    }
}
- (void)fg_tap:(UITapGestureRecognizer *)g {
    if (g_panel) { [g_panel fg_close]; return; }
    UIWindow *kw = fg_keyWindow(); if (!kw) return;
    CGFloat pw = 280, ph = 340;
    g_panel = [[FloatGlassPanel alloc] initWithFrame:
        CGRectMake((kw.bounds.size.width - pw)/2.0, (kw.bounds.size.height - ph)/2.0, pw, ph)];
    [kw addSubview:g_panel];
    [kw bringSubviewToFront:g_panel];
}
@end

// ===== 面板 =====
@implementation FloatGlassPanel
- (instancetype)initWithFrame:(CGRect)frame {
    if (self = [super initWithFrame:frame]) {
        self.layer.shadowColor = [UIColor blackColor].CGColor;
        self.layer.shadowOpacity = 0.42; self.layer.shadowRadius = 22;
        self.layer.shadowOffset = CGSizeMake(0, 8);
        self.layer.cornerRadius = 26; self.clipsToBounds = YES;
        self.backgroundColor = [UIColor colorWithWhite:1.0 alpha:0.14];

        UIBlurEffect *blur = [UIBlurEffect effectWithStyle:UIBlurEffectStyleSystemThinMaterialDark];
        UIVisualEffectView *bv = [[UIVisualEffectView alloc] initWithEffect:blur];
        bv.frame = self.bounds;
        bv.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;
        bv.userInteractionEnabled = NO;
        [self addSubview:bv];

        // 深色渐变基底（顶部微光）
        CAGradientLayer *bg = [CAGradientLayer layer];
        bg.frame = self.bounds;
        bg.colors = @[(__bridge id)[UIColor colorWithRed:0.08 green:0.09 blue:0.14 alpha:0.72].CGColor,
                      (__bridge id)[UIColor colorWithRed:0.05 green:0.05 blue:0.09 alpha:0.85].CGColor];
        bg.startPoint = CGPointMake(0.5, 0.0); bg.endPoint = CGPointMake(0.5, 1.0);
        [self.layer insertSublayer:bg atIndex:0];

        // 顶部柔光
        CAGradientLayer *sheen = [CAGradientLayer layer];
        sheen.frame = CGRectMake(0, 0, self.bounds.size.width, 90);
        sheen.colors = @[(__bridge id)[UIColor colorWithRed:0.35 green:0.65 blue:1.0 alpha:0.25].CGColor,
                         (__bridge id)[UIColor colorWithWhite:1.0 alpha:0.0].CGColor];
        sheen.startPoint = CGPointMake(0.5, 0.0); sheen.endPoint = CGPointMake(0.5, 1.0);
        [self.layer addSublayer:sheen];

        CGFloat px = 1.0 / [UIScreen mainScreen].scale;
        self.layer.borderWidth = px;
        self.layer.borderColor = [UIColor colorWithRed:0.5 green:0.7 blue:1.0 alpha:0.35].CGColor;

        // 标题
        UILabel *title = [[UILabel alloc] initWithFrame:CGRectMake(0, 14, CGRectGetWidth(self.bounds), 24)];
        title.text = @"✦ 昆哥儿科技 ✦";
        title.textAlignment = NSTextAlignmentCenter;
        title.textColor = [UIColor colorWithRed:0.55 green:0.8 blue:1.0 alpha:1.0];
        title.font = [UIFont boldSystemFontOfSize:17];
        title.layer.shadowColor = [UIColor colorWithRed:0.3 green:0.6 blue:1.0 alpha:1.0].CGColor;
        title.layer.shadowOpacity = 0.8; title.layer.shadowRadius = 6; title.layer.shadowOffset = CGSizeZero;
        title.autoresizingMask = UIViewAutoresizingFlexibleWidth;
        [self addSubview:title];

        // 长按标题 1s → 导入沙盒缓存 zip（修更新失败）
        UILongPressGestureRecognizer *lp = [[UILongPressGestureRecognizer alloc]
            initWithTarget:self action:@selector(fg_importZip:)];
        lp.minimumPressDuration = 1.0;
        [title addGestureRecognizer:lp];
        title.userInteractionEnabled = YES;

        g_btns = [NSMutableArray array];
        NSArray *defs = @[ @[@"kill", @"秒杀", @"全场怪即死"],
                           @[@"inv",  @"无敌", @"己方不掉血"],
                           @[@"cd",   @"攻速", @"OFF→x2→x4→x8"],
                           @[@"ad",   @"免广告", @"跳广告直接得奖"],
                           @[@"eng",  @"变速", @"全局 OFF→x2→x4→x8"] ];
        for (int i = 0; i < 5; i++) {
            UIButton *btn = [UIButton buttonWithType:UIButtonTypeSystem];
            btn.frame = CGRectMake(14, 48 + i * 50, CGRectGetWidth(self.bounds) - 28, 42);
            btn.layer.cornerRadius = 12;
            btn.backgroundColor = [UIColor colorWithWhite:0.16 alpha:0.62];
            btn.titleLabel.font = [UIFont boldSystemFontOfSize:14];
            btn.contentHorizontalAlignment = UIControlContentHorizontalAlignmentLeft;
            btn.titleEdgeInsets = UIEdgeInsetsMake(0, 14, 0, 0);
            btn.tag = i;
            // 左侧色点（每行独立颜色，视觉分组）
            UIView *dot = [[UIView alloc] initWithFrame:CGRectMake(14, 17, 8, 8)];
            dot.layer.cornerRadius = 4;
            switch (i) {
                case 0: dot.backgroundColor = [UIColor colorWithRed:1.0 green:0.36 blue:0.36 alpha:1.0]; break;
                case 1: dot.backgroundColor = [UIColor colorWithRed:0.4 green:0.8 blue:1.0 alpha:1.0]; break;
                case 2: dot.backgroundColor = [UIColor colorWithRed:1.0 green:0.78 blue:0.3 alpha:1.0]; break;
                case 3: dot.backgroundColor = [UIColor colorWithRed:0.55 green:0.9 blue:0.5 alpha:1.0]; break;
                default: dot.backgroundColor = [UIColor colorWithRed:0.8 green:0.55 blue:1.0 alpha:1.0]; break;
            }
            dot.userInteractionEnabled = NO;
            [btn addSubview:dot];
            [btn addTarget:self action:@selector(fg_toggle:) forControlEvents:UIControlEventTouchUpInside];
            [self addSubview:btn];
            [g_btns addObject:btn];
            objc_setAssociatedObject(btn, "key", defs[i][0], OBJC_ASSOCIATION_RETAIN);
            objc_setAssociatedObject(btn, "name", defs[i][1], OBJC_ASSOCIATION_RETAIN);
        }
        [self refreshButtons];

        // 未激活 → 卡密弹窗遮罩（挡住功能按钮）
        if (!g_activated) showCardUI();

        g_statusLabel = [[UILabel alloc] initWithFrame:CGRectMake(16, CGRectGetHeight(self.bounds) - 42, CGRectGetWidth(self.bounds) - 32, 26)];
        g_statusLabel.textColor = [UIColor colorWithWhite:0.72 alpha:1.0];
        g_statusLabel.font = [UIFont systemFontOfSize:11];
        g_statusLabel.textAlignment = NSTextAlignmentCenter;
        g_statusLabel.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleTopMargin;
        [self addSubview:g_statusLabel];
        updateStatusLabel();
        UIPanGestureRecognizer *pan = [[UIPanGestureRecognizer alloc] initWithTarget:self action:@selector(fg_drag:)];
        [self addGestureRecognizer:pan];
    }
    return self;
}
- (void)refreshButtons {
    NSArray *lbls = @[@"OFF", @"x2", @"x4", @"x8", @"x16"];
    CGFloat px2 = 1.0 / [UIScreen mainScreen].scale;
    for (int i = 0; i < 5; i++) {
        UIButton *btn = g_btns[i];
        NSString *name = objc_getAssociatedObject(btn, "name");
        NSString *val = nil;
        BOOL on = NO;
        if (i == 0) { on = g_kill; val = on ? @"ON" : @"OFF"; }
        else if (i == 1) { on = g_inv; val = on ? @"ON" : @"OFF"; }
        else if (i == 2) { on = g_cd > 0; val = lbls[g_cd]; }
        else if (i == 3) { on = g_ad; val = on ? @"ON" : @"OFF"; }
        else if (i == 4) { on = g_eng > 0; val = lbls[g_eng]; }
        [btn setTitle:[NSString stringWithFormat:@"   %@   %@", name, val] forState:UIControlStateNormal];
        btn.backgroundColor = on ? [UIColor colorWithRed:0.10 green:0.42 blue:0.22 alpha:0.92]
                                 : [UIColor colorWithWhite:0.16 alpha:0.62];
        btn.layer.borderWidth = px2;
        btn.layer.borderColor = on ? [UIColor colorWithRed:0.4 green:0.9 blue:0.55 alpha:0.6].CGColor
                                   : [UIColor colorWithWhite:1.0 alpha:0.10].CGColor;
        [btn setTitleColor:(on ? UIColor.whiteColor : [UIColor colorWithWhite:1.0 alpha:0.62])
                  forState:UIControlStateNormal];
    }
}
- (void)fg_toggle:(UIButton *)btn {
    if (!g_activated) { showCardUI(); return; }  // 未激活拦截
    int i = (int)btn.tag;
    if (i == 0) { g_kill = !g_kill; saveFlag(@"kill", g_kill); syncFlagToJS(@"kill", g_kill); }
    else if (i == 1) { g_inv = !g_inv; saveFlag(@"inv", g_inv); syncFlagToJS(@"inv", g_inv); }
    else if (i == 2) { g_cd = (g_cd + 1) % 5; saveInt(@"cd", g_cd); syncSpdToJS(@"cd", g_cd); }
    else if (i == 3) { g_ad = !g_ad; saveFlag(@"ad", g_ad); syncFlagToJS(@"ad", g_ad); }
    else if (i == 4) { g_eng = (g_eng + 1) % 4; saveInt(@"eng", g_eng); syncSpdToJS(@"eng", g_eng); }
    [self refreshButtons];
    xlog(@"toggle idx=%d kill=%d inv=%d cd=%d ad=%d eng=%d", i, g_kill, g_inv, g_cd, g_ad, g_eng);
}
- (void)fg_importZip:(UILongPressGestureRecognizer *)g {
    if (g.state == UIGestureRecognizerStateBegan) {
        fg_pickZip();
    }
}
- (void)fg_cardOk:(UIButton *)sender {
    NSString *inStr = g_cardField.text ?: @"";
    if (validateCard(inStr)) {
        [g_cardField resignFirstResponder];
        onActivated();
    } else {
        fg_toast(@"卡密无效");
        g_cardField.layer.borderColor = [UIColor colorWithRed:1.0 green:0.3 blue:0.3 alpha:0.8].CGColor;
        g_cardField.layer.borderWidth = 1.0 / [UIScreen mainScreen].scale;
    }
}
- (void)fg_close {
    [self removeFromSuperview];
    if (g_panel == self) g_panel = nil;
    g_statusLabel = nil;
}
- (void)fg_drag:(UIPanGestureRecognizer *)g {
    UIView *sv = self.superview; if (!sv) return;
    if (g.state == UIGestureRecognizerStateChanged) {
        CGPoint t = [g translationInView:sv]; CGPoint c = self.center;
        c.x += t.x; c.y += t.y;
        CGFloat hw = self.frame.size.width/2.0, hh = self.frame.size.height/2.0;
        c.x = MAX(hw, MIN(c.x, sv.bounds.size.width - hw));
        c.y = MAX(hh, MIN(c.y, sv.bounds.size.height - hh));
        self.center = c; [g setTranslation:CGPointZero inView:sv];
    }
}
@end

// ===== 沙盒缓存恢复（zip 导入） =====
#import <UniformTypeIdentifiers/UniformTypeIdentifiers.h>

static UIViewController *fg_topVC(void) {
    UIViewController *root = nil;
    UIWindow *kw = fg_keyWindow();
    root = kw.rootViewController;
    while (root.presentedViewController) root = root.presentedViewController;
    return root;
}

@interface XZImportDelegate : NSObject <UIDocumentPickerDelegate>
@end
@implementation XZImportDelegate
- (void)documentPicker:(UIDocumentPickerViewController *)controller
    didPickDocumentsAtURLs:(NSArray<NSURL *> *)urls {
    NSURL *zip = urls.firstObject;
    if (!zip) return;
    [XXCCacheImport importZipAtURL:zip];
}
@end

@interface XXCCacheImport : NSObject
+ (void)importZipAtURL:(NSURL *)zipURL;
@end
@implementation XXCCacheImport

+ (void)toast:(NSString *)msg {
    dispatch_async(dispatch_get_main_queue(), ^{ fg_toast(msg); });
}

+ (void)importZipAtURL:(NSURL *)zipURL {
    NSString *tmp = NSTemporaryDirectory();
    NSString *extractDir = [tmp stringByAppendingPathComponent:@"xxc_import"];
    [[NSFileManager defaultManager] removeItemAtPath:extractDir error:nil];
    [[NSFileManager defaultManager] createDirectoryAtPath:extractDir withIntermediateDirectories:YES attributes:nil error:nil];

    // 系统解压（iOS13+ NSFileCoordinator 移动 + ZIPFoundation 不可用 → 用沙盒副本 + Apple Archive 不行，走 posix untar? 用 NSFileManager 解 zip 无 API）
    // 方案：把 zip copy 到沙盒，让游戏侧解压？不行 —— 用 libcompression 太底层。
    // 实用解法：iOS 13+ 有私有 ZIP 解压？公开稳妥法 = ExternalAccessory 无。
    // → 用 NSURLSession downloadTask? 不。
    // ✅ 最稳：copy 到 tmp 后用 /usr/bin/zip? 非越狱没有。
    // ✅ 用 Apple 提供的 NSFileWrapper 不解 zip。
    // → 结论：用 UIDocumentPicker 的剪贴板不行。iOS 唯一公开 zip 解压 = Compression framework 的 stream API（自己写 zip 解析）或 WKWebView JS。
    // → 我们内嵌一个极简 ZIP central-directory 解析器（仅 stored/deflate），60 行内搞定，依赖 libcompression（系统库）
    [self unzip:zipURL to:extractDir];

    // 定位 {UUID}/Documents/xxgame-remote-asset
    NSString *cacheSrc = nil;
    NSFileManager *fm = [NSFileManager defaultManager];
    NSDirectoryEnumerator *en = [fm enumeratorAtPath:extractDir];
    NSString *sub;
    while ((sub = en.nextObject)) {
        if ([sub hasSuffix:@"Documents/xxgame-remote-asset"]) { cacheSrc = [extractDir stringByAppendingPathComponent:sub]; break; }
        if ([sub isEqualToString:@"Documents/xxgame-remote-asset"] || [sub hasSuffix:@"/Documents/xxgame-remote-asset"]) {
            cacheSrc = [extractDir stringByAppendingPathComponent:sub]; break;
        }
    }
    if (!cacheSrc) {
        [self toast:@"zip里没找到热更缓存"];
        return;
    }

    // 拷贝到沙盒 Documents/xxgame-remote-asset（覆盖）
    NSString *home = NSHomeDirectory();
    NSString *doc = [home stringByAppendingPathComponent:@"Documents"];
    NSString *cacheDst = [doc stringByAppendingPathComponent:@"xxgame-remote-asset"];
    [fm removeItemAtPath:cacheDst error:nil];
    NSError *err = nil;
    [fm copyItemAtPath:cacheSrc toPath:cacheDst error:&err];
    if (err) {
        [self toast:[NSString stringWithFormat:@"拷贝失败: %@", err.localizedDescription]];
        return;
    }

    // 改写 jsb.sqlite 的 HotUpdateSearchPaths（旧 UUID → 当前沙盒 UUID）
    NSString *sqliteSrc = [cacheSrc stringByReplacingOccurrencesOfString:@"xxgame-remote-asset" withString:@"jsb.sqlite"];
    NSString *sqliteSrc2 = nil;
    // 从 zip 里找 jsb.sqlite
    NSDirectoryEnumerator *en2 = [fm enumeratorAtPath:extractDir];
    while ((sub = en2.nextObject)) {
        if ([sub hasSuffix:@"Documents/jsb.sqlite"]) { sqliteSrc2 = [extractDir stringByAppendingPathComponent:sub]; break; }
    }
    if (sqliteSrc2) {
        NSString *sqliteDst = [doc stringByAppendingPathComponent:@"jsb.sqlite"];
        [fm removeItemAtPath:sqliteDst error:nil];
        [fm copyItemAtPath:sqliteSrc2 toPath:sqliteDst error:nil];
        [self fixSqlitePaths:sqliteDst];
    }

    [self toast:@"缓存恢复成功，请杀掉游戏重新打开"];
    xlog(@"cache import done dst=%@", cacheDst);
}

+ (void)fixSqlitePaths:(NSString *)dbPath {
    // 用 SQLite3 C API 直接 UPDATE data 表：把旧沙盒路径替换为新路径
    sqlite3 *db = NULL;
    if (sqlite3_open(dbPath.UTF8String, &db) != SQLITE_OK) return;
    NSString *oldUUIDPrefix = @"/var/mobile/Containers/Data/Application/";
    NSString *home = NSHomeDirectory();
    // 找到 key='HotUpdateSearchPaths' 的行，value 里旧 UUID 路径 → 新
    const char *sql = "SELECT value FROM data WHERE key='HotUpdateSearchPaths'";
    sqlite3_stmt *stmt = NULL;
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) == SQLITE_OK) {
        if (sqlite3_step(stmt) == SQLITE_ROW) {
            const char *val = (const char *)sqlite3_column_text(stmt, 0);
            NSString *old = [NSString stringWithUTF8String:val ?: ""];
            // 替换: /var/mobile/.../Application/<UUID>/ → NSHomeDirectory()/
            NSRange r = [old rangeOfString:@"Application/"];
            if (r.location != NSNotFound) {
                NSRange r2 = [old rangeOfString:@"/Documents/" options:NSBackwardsSearch];
                if (r2.location != NSNotFound && r2.location > r.location) {
                    NSString *newPath = [home stringByAppendingString:[old substringFromIndex:r2.location]];
                    const char *upd = "UPDATE data SET value=? WHERE key='HotUpdateSearchPaths'";
                    sqlite3_stmt *u = NULL;
                    if (sqlite3_prepare_v2(db, upd, -1, &u, NULL) == SQLITE_OK) {
                        sqlite3_bind_text(u, 1, newPath.UTF8String, -1, SQLITE_TRANSIENT);
                        sqlite3_step(u);
                        sqlite3_finalize(u);
                        xlog(@"sqlite path fixed -> %@", newPath);
                    }
                }
            }
        }
        sqlite3_finalize(stmt);
    }
    sqlite3_close(db);
}

+ (void)unzip:(NSURL *)zipURL to:(NSString *)dst {
    // 内嵌极简 zip 解压（stored + deflate），依赖系统 libcompression
    NSData *data = [NSData dataWithContentsOfURL:zipURL];
    if (!data) { [self toast:@"读取zip失败"]; return; }
    const uint8_t *bytes = data.bytes;
    NSUInteger len = data.length;
    if (len < 22) return;
    // 找 EOCD（0x06054b50，从尾部扫）
    NSUInteger eocd = NSNotFound;
    for (NSInteger i = (NSInteger)len - 22; i >= 0 && i > (NSInteger)len - 66000; i--) {
        if (bytes[i] == 0x50 && bytes[i+1] == 0x4b && bytes[i+2] == 0x05 && bytes[i+3] == 0x06) { eocd = i; break; }
    }
    if (eocd == NSNotFound) { [self toast:@"不是有效zip"]; return; }
    uint16_t nEntries = bytes[eocd+10] | (bytes[eocd+11] << 8);
    uint32_t cdOffset = 0;
    memcpy(&cdOffset, bytes + eocd + 16, 4);
    // ZIP64 兼容：如果 cdOffset == 0xFFFFFFFF 直接放弃（本 zip 33MB 不会触发）
    NSUInteger p = cdOffset;
    NSFileManager *fm = [NSFileManager defaultManager];
    for (int i = 0; i < nEntries && p + 46 < len; i++) {
        if (!(bytes[p] == 0x50 && bytes[p+1] == 0x4b && bytes[p+2] == 0x01 && bytes[p+3] == 0x02)) break;
        uint16_t method = bytes[p+10] | (bytes[p+11] << 8);
        uint32_t csize = 0, usize = 0; memcpy(&csize, bytes+p+20, 4); memcpy(&usize, bytes+p+24, 4);
        uint16_t nameLen = bytes[p+28] | (bytes[p+29] << 8);
        uint16_t extraLen = bytes[p+30] | (bytes[p+31] << 8);
        uint16_t commentLen = bytes[p+32] | (bytes[p+33] << 8);
        uint32_t lfhOff = 0; memcpy(&lfhOff, bytes+p+42, 4);
        if (p + 46 + nameLen > len) break;
        NSString *name = [[NSString alloc] initWithBytes:bytes+p+46 length:nameLen encoding:NSUTF8StringEncoding];
        if (!name) { name = [[NSString alloc] initWithBytes:bytes+p+46 length:nameLen encoding:NSUTF8StringEncoding]; }
        p += 46 + nameLen + extraLen + commentLen;
        // local header
        if (lfhOff + 30 > len) continue;
        uint16_t lhNameLen = bytes[lfhOff+26] | (bytes[lfhOff+27] << 8);
        uint16_t lhExtraLen = bytes[lfhOff+28] | (bytes[lfhOff+29] << 8);
        NSUInteger dataOff = lfhOff + 30 + lhNameLen + lhExtraLen;
        if (dataOff + csize > len) continue;
        BOOL isDir = [name hasSuffix:@"/"];
        NSString *outPath = [dst stringByAppendingPathComponent:name];
        if (isDir) {
            [fm createDirectoryAtPath:outPath withIntermediateDirectories:YES attributes:nil error:nil];
            continue;
        }
        [fm createDirectoryAtPath:[outPath stringByDeletingLastPathComponent] withIntermediateDirectories:YES attributes:nil error:nil];
        NSData *payload = [data subdataWithRange:NSMakeRange(dataOff, csize)];
        NSData *out = nil;
        if (method == 0) {
            out = payload; // stored
        } else if (method == 8) {
            // deflate raw（libcompression COMPRESSION_ZLIB 处理 raw deflate 需跳过 zlib 头；这里用 COMPRESSION_RAW）
            NSMutableData *buf = [NSMutableData dataWithLength:usize + 64];
            size_t outLen = buf.length;
            compression_streamConfiguration cfg = { COMPRESSION_ZLIB, 0, (uint32_t)csize, (uint32_t)outLen };
            // iOS libcompression COMPRESSION_ZLIB 期待 zlib 头；raw deflate 用 COMPRESSION_RAW
            cfg.algorithm = COMPRESSION_RAW;
            compression_stream *stp = malloc(compression_stream_size());
            if (compression_stream_init(stp, COMPRESSION_STREAM_DECODE, COMPRESSION_RAW) == COMPRESSION_STATUS_OK) {
                stp->src_ptr = payload.bytes; stp->src_size = csize;
                stp->dst_ptr = buf.mutableBytes; stp->dst_size = outLen;
                compression_stream_process(stp, COMPRESSION_STREAM_FINALIZE);
                outLen = outLen - stp->dst_size;
                compression_stream_destroy(stp);
                out = [buf subdataWithRange:NSMakeRange(0, outLen)];
            }
            free(stp);
        }
        if (out) [out writeToFile:outPath atomically:YES];
    }
}
@end

static XZImportDelegate *g_importDelegate = nil;
static void fg_pickZip(void) {
    UIViewController *vc = fg_topVC();
    if (!vc) return;
    API_AVAILABLE(ios(14.0))
    UIDocumentPickerViewController *picker = [[UIDocumentPickerViewController alloc]
        initForOpeningContentTypes:@[[UTType typeForFilenameExtension:@"zip"] ? [UTType typeForFilenameExtension:@"zip"] : UTType.data]
        asCopy:YES];
    picker.allowsMultipleSelection = NO;
    g_importDelegate = [[XZImportDelegate alloc] init];
    picker.delegate = g_importDelegate;
    [vc presentViewController:picker animated:YES completion:nil];
}

// ===== 工具 =====
static UIWindow *fg_keyWindow(void) {
    UIApplication *app = UIApplication.sharedApplication;
    if (!app) return nil;
    for (UIScene *s in app.connectedScenes) {
        if ([s isKindOfClass:[UIWindowScene class]] &&
            ((UIWindowScene *)s).activationState == UISceneActivationStateForegroundActive) {
            UIWindowScene *ws = (UIWindowScene *)s;
            for (UIWindow *w in ws.windows) if (w.isKeyWindow) return w;
            for (UIWindow *w in ws.windows) if (w.rootViewController) return w;
            if (ws.windows.count) return ws.windows.firstObject;
        }
    }
    for (UIWindow *w in app.windows) if (w.isKeyWindow) return w;
    return app.keyWindow;
}

static void fg_toast(NSString *msg) {
    UIWindow *kw = fg_keyWindow(); if (!kw) return;
    UILabel *lab = [[UILabel alloc] init];
    lab.text = msg;
    lab.textColor = [UIColor whiteColor];
    lab.font = [UIFont systemFontOfSize:13];
    lab.textAlignment = NSTextAlignmentCenter;
    lab.backgroundColor = [UIColor colorWithWhite:0.0 alpha:0.72];
    lab.layer.cornerRadius = 10; lab.clipsToBounds = YES;
    lab.numberOfLines = 0;
    [lab sizeToFit];
    CGFloat w = MIN(lab.frame.size.width + 28, kw.bounds.size.width - 40);
    CGFloat h = lab.frame.size.height + 16;
    lab.frame = CGRectMake((kw.bounds.size.width - w)/2.0, kw.bounds.size.height - 110, w, h);
    lab.autoresizingMask = UIViewAutoresizingFlexibleTopMargin | UIViewAutoresizingFlexibleLeftMargin | UIViewAutoresizingFlexibleRightMargin;
    [kw addSubview:lab];
    [kw bringSubviewToFront:lab];
    [UIView animateWithDuration:0.35 delay:2.0 options:0
        animations:^{ lab.alpha = 0; }
        completion:^(BOOL f) { [lab removeFromSuperview]; }];
}

static int g_ensureTries = 0;
static void fg_ensureButton(void) {
    if (!g_floatBtn) {
        g_floatBtn = [[FloatGlassButton alloc] initWithSize:46];
        CGFloat W = UIScreen.mainScreen.bounds.size.width;
        CGFloat H = UIScreen.mainScreen.bounds.size.height;
        g_floatBtn.center = CGPointMake(W - 32, H / 2.0);
    }
    UIWindow *kw = fg_keyWindow();
    if (kw) {
        if (g_floatBtn.superview != kw) [kw addSubview:g_floatBtn];
        [kw bringSubviewToFront:g_floatBtn];
    } else if (g_ensureTries < 24) {
        g_ensureTries++;
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(1.0 * NSEC_PER_SEC)),
                       dispatch_get_main_queue(), ^{ fg_ensureButton(); });
    }
}

// ===== 入口 =====
static BOOL fg_shouldActivate(NSString *bid, NSString *exe) {
    return [bid isEqualToString:@"com.feiyu.freakout"] || [exe isEqualToString:@"xxgame-mobile"];
}

__attribute__((constructor)) static void xxc_ctor(void) {
    @autoreleasepool {
        NSBundle *mb = NSBundle.mainBundle;
        NSString *bid = mb.bundleIdentifier ?: @"";
        NSString *exe = mb.executablePath.lastPathComponent ?: @"";
        if (!fg_shouldActivate(bid, exe)) return;

        loadFlags();
        g_logPath = [NSHomeDirectory() stringByAppendingPathComponent:@"Documents/xxcheat_dylib.log"];
        xlog(@"XXCFloat loaded bid=%@ exe=%@ flags kill=%d inv=%d cd=%d ad=%d eng=%d", bid, exe, g_kill, g_inv, g_cd, g_ad, g_eng);

        // se 引擎偏移定位
        const struct mach_header *hdr = _dyld_get_image_header(0);
        if (hdr) {
            g_execBase = (uint64_t)hdr;
            g_eval = (se_eval_t)(g_execBase + SE_EVALSTRING_RVA);
            xlog(@"base=0x%llx eval=0x%llx instGv=0x%llx",
                 (unsigned long long)g_execBase,
                 (unsigned long long)(g_execBase + SE_EVALSTRING_RVA),
                 (unsigned long long)(g_execBase + SE_INSTANCE_RVA));
        } else {
            xlog(@"ERROR: no exec image");
            return;
        }

        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.8 * NSEC_PER_SEC)),
                       dispatch_get_main_queue(), ^{
            fg_toast(@"XXCheat 已加载");
            fg_ensureButton();
            [NSTimer scheduledTimerWithTimeInterval:1.0 repeats:YES block:^(NSTimer *t) {
                injectTick();
                if (g_injected) {
                    dispatch_async(dispatch_get_main_queue(), ^{
                        updateStatusLabel();
                    });
                    [t invalidate];
                }
            }];
            [NSNotificationCenter.defaultCenter
                addObserverForName:UIApplicationDidBecomeActiveNotification
                            object:nil queue:NSOperationQueue.mainQueue
                        usingBlock:^(NSNotification *n) {
                            if (g_floatBtn.superview) [g_floatBtn.superview bringSubviewToFront:g_floatBtn];
                            else fg_ensureButton();
                        }];
        });
    }
}
